python3 -c "
import numpy as np
L=open('opt1.xyz').read().split('\n')
n=int(L[0]); at=[];xyz=[]
for l in L[2:2+n]:
    p=l.split(); at.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
ag=at.index('Ag'); b=at.index('B')
for i in range(n):
    d=np.linalg.norm(xyz[i]-xyz[ag])
    if d<3.0 and i!=ag: print('Ag',i,at[i],round(d,2))
print('---B')
for i in range(n):
    d=np.linalg.norm(xyz[i]-xyz[b])
    if d<2.0 and i!=b: print('B',i,at[i],round(d,2))
"
